// Settings button + printable station QR code modal.
// Usage: <div id="settings-slot"></div> where the button should go, then
// <script src="assets/qr-modal.js" data-base=""></script> (data-base = path prefix to repo root).
// QR images live in assets/qr/ and are generated by scripts/make_qr_pdf.py (same URLs as the PDF).
(function () {
    var me = document.currentScript;
    var base = (me && me.getAttribute('data-base')) || '';
    var PAGES = [
        ['Station Menu', 'Start here', 'station-menu'],
        ['Business Law', 'The $67 Million Pants', 'business-law'],
        ['Management', 'Back-to-Back Drawing', 'management'],
        ['Accounting', 'The Year-Long Skimming Operation', 'accounting'],
        ['Investments', 'Buy or Sell? Historical Market Quiz', 'investments'],
        ['Marketing', 'Build a Bottled Water Brand', 'marketing'],
        ['Entrepreneurship', 'The $50 Million Pitch', 'entrepreneurship'],
        ['Graphic Design', 'Keep It or Scrap It?', 'graphic-design'],
        ['Station Worksheet', 'Google Doc: File \u2192 Make a copy', 'station-worksheet']
    ];

    var css = document.createElement('style');
    css.textContent =
        '#qr-modal{position:fixed;inset:0;z-index:100;background:rgba(2,6,23,.75);display:none;overflow:auto;padding:24px}' +
        '#qr-modal.open{display:block}' +
        '#qr-modal .qr-sheet{max-width:960px;margin:0 auto;background:#fff;color:#0f172a;border-radius:16px;padding:24px}' +
        '#qr-modal .qr-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px}' +
        '#qr-modal .qr-card{border:2px solid #e2e8f0;border-radius:12px;padding:14px;text-align:center;break-inside:avoid;page-break-inside:avoid}' +
        '#qr-modal .qr-card h3{font-size:18px;font-weight:800;margin:0}' +
        '#qr-modal .qr-card p{font-size:12px;color:#475569;margin:2px 0 8px}' +
        '#qr-modal .qr-card img{width:100%;max-width:200px;aspect-ratio:1;margin:0 auto;display:block}' +
        '@media print{body.qr-printing>*:not(#qr-modal){display:none!important}' +
        'body.qr-printing{background:#fff!important}' +
        'body.qr-printing #qr-modal{position:static;display:block;background:#fff;padding:0;overflow:visible}' +
        'body.qr-printing #qr-modal .qr-sheet{max-width:none;padding:0;border-radius:0}' +
        'body.qr-printing #qr-modal .qr-actions{display:none!important}' +
        'body.qr-printing #qr-modal .qr-grid{grid-template-columns:repeat(3,1fr)}}';
    document.head.appendChild(css);

    var cards = PAGES.map(function (p) {
        return '<div class="qr-card"><h3>' + p[0] + '</h3><p>' + p[1] + '</p>' +
            '<img src="' + base + 'assets/qr/' + p[2] + '.svg" alt="QR code for ' + p[0] + '"></div>';
    }).join('');

    var modal = document.createElement('div');
    modal.id = 'qr-modal';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');
    modal.setAttribute('aria-label', 'Station QR codes');
    modal.innerHTML =
        '<div class="qr-sheet">' +
        '<div class="qr-actions" style="display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:12px;margin-bottom:16px">' +
        '<div><h2 style="font-size:22px;font-weight:800;margin:0">Station QR Codes</h2>' +
        '<p style="font-size:13px;color:#475569;margin:2px 0 0">Print and post each code at its station. Full-page posters: <a href="' + base + 'assets/station-qr-codes.pdf" target="_blank" style="color:#b45309;font-weight:600;text-decoration:underline">station-qr-codes.pdf</a></p></div>' +
        '<div style="display:flex;gap:8px"><button type="button" id="qr-print-btn" style="background:#f59e0b;color:#020617;font-weight:700;padding:8px 16px;border-radius:10px">Print</button>' +
        '<button type="button" id="qr-close-btn" style="background:#e2e8f0;color:#0f172a;font-weight:600;padding:8px 16px;border-radius:10px">Close</button></div></div>' +
        '<div class="qr-grid">' + cards + '</div></div>';

    function open() { modal.classList.add('open'); document.body.style.overflow = 'hidden'; }
    function close() { modal.classList.remove('open'); document.body.style.overflow = ''; }

    function init() {
        document.body.appendChild(modal);
        var slot = document.getElementById('settings-slot');
        if (slot) {
            slot.outerHTML = '<button type="button" id="settings-btn" class="px-3 py-1.5 rounded-lg border border-slate-800 hover:bg-slate-800 text-slate-300 hover:text-slate-100 transition flex items-center gap-1.5 text-xs font-medium" title="Settings: printable QR codes">' +
                '<i data-lucide="settings" class="w-3.5 h-3.5 text-amber-400"></i><span>Settings</span></button>';
            document.getElementById('settings-btn').addEventListener('click', open);
            if (window.lucide) lucide.createIcons();
        }
        document.getElementById('qr-close-btn').addEventListener('click', close);
        document.getElementById('qr-print-btn').addEventListener('click', function () {
            document.body.classList.add('qr-printing');
            window.print();
        });
        window.addEventListener('afterprint', function () { document.body.classList.remove('qr-printing'); });
        modal.addEventListener('click', function (e) { if (e.target === modal) close(); });
        document.addEventListener('keydown', function (e) { if (e.key === 'Escape') close(); });
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
    window.openQrModal = open;
})();
